// Package config loads all runtime configuration from environment variables.
//
// In OpenShift, DATABASE_URL comes from the Crunchy PostgresCluster user
// secret, and the BUCKET_* / AWS_* variables come from the ConfigMap and
// Secret generated by the ObjectBucketClaim (ODF / NooBaa).
package config

import (
	"fmt"
	"os"
	"strconv"
)

type Config struct {
	Port        string
	DatabaseURL string

	// Object storage (S3-compatible, provisioned by an ObjectBucketClaim).
	BucketHost   string
	BucketPort   string
	BucketName   string
	S3AccessKey  string
	S3SecretKey  string
	S3UseSSL     bool
	// LocalStorageDir is a filesystem fallback used when no bucket is
	// configured (local development without ODF).
	LocalStorageDir string

	// OCR service used for PDF / image statements.
	OCREndpoint string
	OCRAPIKey   string

	MaxUploadBytes int64
	Workers        int

	// Version is the git commit the binary was built from, injected by main
	// from an ldflags variable (not an environment variable).
	Version string
}

func Load() (*Config, error) {
	c := &Config{
		Port:            envOr("PORT", "8080"),
		DatabaseURL:     os.Getenv("DATABASE_URL"),
		BucketHost:      os.Getenv("BUCKET_HOST"),
		BucketPort:      envOr("BUCKET_PORT", "443"),
		BucketName:      os.Getenv("BUCKET_NAME"),
		S3AccessKey:     os.Getenv("AWS_ACCESS_KEY_ID"),
		S3SecretKey:     os.Getenv("AWS_SECRET_ACCESS_KEY"),
		S3UseSSL:        envOr("BUCKET_USE_SSL", "true") == "true",
		LocalStorageDir: envOr("LOCAL_STORAGE_DIR", ""),
		OCREndpoint:     os.Getenv("OCR_ENDPOINT"),
		OCRAPIKey:       os.Getenv("OCR_API_KEY"),
		MaxUploadBytes:  envInt64("MAX_UPLOAD_BYTES", 10<<20), // 10 MB per PRD
		Workers:         int(envInt64("WORKERS", 4)),
	}
	if c.DatabaseURL == "" {
		return nil, fmt.Errorf("DATABASE_URL is required")
	}
	return c, nil
}

func (c *Config) BucketConfigured() bool {
	return c.BucketHost != "" && c.BucketName != ""
}

func (c *Config) S3Endpoint() string {
	return c.BucketHost + ":" + c.BucketPort
}

func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func envInt64(key string, def int64) int64 {
	if v := os.Getenv(key); v != "" {
		if n, err := strconv.ParseInt(v, 10, 64); err == nil {
			return n
		}
	}
	return def
}
